/*global jQuery PubSub*/

'use strict';

//jQuery
var $ = jQuery;

//Internal variables
var _$target,
	_tree,
	_context;

/**
 * Set up the client component, adding the new types to dform
 * @method _setup
 */
function _setup(components, settings, context) {

	_context = $.extend({
		jQuery: jQuery,
		PubSub: PubSub
	}, context, {
		settings: $.extend(true, {
			validate: {
				highlight: function(element) {
					$(element).closest('.form-group').addClass('has-error');
				},
				unhighlight: function(element) {
					$(element).closest('.form-group').removeClass('has-error');
				},
				errorElement: 'span',
				errorClass: 'help-block',
				errorPlacement: function(error, element) {
					if (element.parent('.input-group').length) {
						error.insertAfter(element.parent());
					} else {
						error.insertAfter(element);
					}
				}
			}
		}, settings)
	});

	//Setup dform types
	_setupTypes(components.types);

	//Setup dform subscribers
	_setupSubscribers(components.subscribers);

	//Setup validations
	_setupValidations(components.validations);

	//Init the subcriptions to the type's events
	_typesEvents();

}

/**
 * Render each branch
 * @method _render
 * @param {object} $target Jquery selection where the form tree will be rendered
 * @param {object} tree JSON with all instructions to render the form tree
 */
function _render(target, tree) {

	//Save the internal variables
	_tree = tree;
	_$target = $(target);

	//Create and render the branches
	_renderBranches();

}

/**
 * Render each branch
 * @method _renderBranches
 */
function _renderBranches() {
	
	//For each branch
	for (var i = 0; i < _tree.branches.length; i++) {
		var branch = _tree.branches[i];

		//Show only the first branch
		branch['class'] = i === 0 ? 'f3-branch' : 'f3-branch hidden';

		if(branch.selector) {

			//Append each branch on the branch selector
			$(branch.selector).dform(branch);

		} else {

			//Append each branch on the target selector
			_$target.dform(branch);

		}
	}

}

/**
 * Setups dform types
 * @method _setupTypes
 */
function _setupTypes(types) {

	//Loop over all types and init them
	$.each(types, function (typeName, type) {

		$.dform.addType(typeName, function (options) {
			return type.render.call(this, _context, options);
		});

	});

}

/**
 * Setups dform subscribers
 * @method _addSubscribers
 */
function _setupSubscribers(subscribers) {

	//Loop over all subscribers and init them
	$.each(subscribers, function (subscriberName, subscriber) {

		$.dform.subscribe(subscriberName, function(options, type) {
			return subscriber.attach.call(this, _context, options, type);
		});

	});

}

/**
 * Add new validations to jquery validate
 * @method _setupValidations
 */
function _setupValidations(validations) {

	//Loop over all subscribers and init them
	$.each(validations, function (validation) {

		validations[validation].setup(_context);

	});

}

/**
 * Init the subscriptions to the events of the types
 * @method _typesSubscriptions
 */
function _typesEvents() {

	//Decision subscription
	PubSub.subscribe('f3.decision', _decisionTypeEvents);

	//Next subscription
	PubSub.subscribe('f3.next', _nextTypeEvents);

}

/**
 * Function to handle a click event from the 'decision' type
 * @method _decisionTypeEvents
 * @param {string} msg Topic of the event
 * @param {object} data Information sent by the trigger
 */
function _decisionTypeEvents(msg, data) {

	//Click event
	if (data.event === 'go') {

		var $trigger = $(data.trigger),
			toBranch = data.branch,
			fromBranch = $trigger.parents('.f3-branch').attr('branch');

		//Go to an specific branch
		_goToBranch(fromBranch, toBranch);

	}

}

/**
 * Function to handle a click event from the 'next' type
 * @method _nextTypeEvents
 * @param {string} msg Topic of the event
 * @param {object} data Information sent by the trigger
 */
function _nextTypeEvents(msg, data) {

	//Click event
	if (data.event === 'go') {

		var $trigger = $(data.trigger),
			toBranch = data.branch,
			fromBranch = $trigger.parents('.f3-branch').attr('branch');

		//Go to an specific branch
		_goToBranch(fromBranch, toBranch);
	}

}

/**
 * Go to a branch
 * @method _goToBranch
 * @param {string} fromBranch Branch where start
 * @param {string} toBranch Branch where go
 */
function _goToBranch(fromBranch, toBranch) {

	//Get all branches
	var $branches = _$target.find('.f3-branch');

	//For every branch...
	$branches.each(function() {

		var $this = $(this);

		//If the branch depth is higher than the current...
		if (_branchDepth($this.attr('branch')) > _branchDepth(fromBranch)) {

			//Hide the branch
			$this.addClass('hidden');

		}

	});

	//Show the active branch
	$branches.filter('[branch="' + toBranch + '"]').removeClass('hidden');

}

/**
 * Reset a branch
 * @method _branchReset
 * @param {string} branch Branch to reset
 */
function _branchReset(branch) {

	var $branch = _$target.find('[branch="' + branch + '"]');

	$branch.find('input:text, input:password, input:file, select, textarea').val('');

	$branch.find('input:radio, input:checkbox').prop('checked', false).prop('selected', false).trigger('change');

	if ($branch.is('[novalidate]')) {

		var validator = $branch.validate();

		$branch.find('.form-group').removeClass('has-error');

		validator.resetForm();

		validator.reset();

	}

}

/**
 * Calculates branch depth as an integer with decimals
 * @method _branchDepth
 * @param {string} id ID of the branch
 * @return {int}
 */
function _branchDepth(id) {

	var split = id.split('.');
	var first = split[0];
	var result;

	if (split.length !== 1){

		split.shift();

		result = parseFloat(first + '.' + split.join(''));

	} else {

		result = parseFloat(first);

	}

	return result;

}

module.exports = {
	setup: _setup,
	render: _render
};
